#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(optparse);library(jsonlite);library(ggplot2);library(igraph);library(ggraph);library(visNetwork);library(htmlwidgets)})
o<-parse_args(OptionParser(option_list=list(make_option('--input',type='character'),make_option('--params',type='character'),make_option('--output',type='character'),make_option('--nodes',type='character',default=NULL))))
out<-o$output;if(is.null(out))out<-getwd();dir.create(out,recursive=TRUE,showWarnings=FALSE)
options(error=function(){writeLines(toJSON(list(error='Interactive network plot failed',detail=geterrmessage(),suggestion='Check input columns and params.json.'),auto_unbox=TRUE,pretty=TRUE),file.path(out,'error.json'));quit(status=1)})
log<-function(x)cat(sprintf('[%s] %s\n',format(Sys.time(),'%F %T'),x),file=file.path(out,'run.log'),append=TRUE)
bad<-function(x,d='',s='Check input columns and params.json.'){writeLines(toJSON(list(error=x,detail=d,suggestion=s),auto_unbox=TRUE,pretty=TRUE),file.path(out,'error.json'));quit(status=1)}
rt<-function(p){if(is.null(p)||!file.exists(p))bad('Input file not found',as.character(p));e<-tolower(tools::file_ext(p));if(e=='csv')read.csv(p,check.names=FALSE,stringsAsFactors=FALSE)else if(e%in%c('tsv','txt'))read.delim(p,check.names=FALSE,stringsAsFactors=FALSE)else bad('Unsupported input file type',e)}
gp<-function(p,n,d=NULL)if(!is.null(p[[n]]))p[[n]]else d;ga<-function(p,n,d=NULL){for(x in n)if(!is.null(p[[x]]))return(p[[x]]);d};bn<-function(x,d=FALSE){if(is.null(x))return(d);if(is.logical(x))return(isTRUE(x[1]));tolower(as.character(x[1]))%in%c('true','t','yes','y','1','on')};vv<-function(x){if(is.null(x))return(character());if(is.list(x))x<-unlist(x);if(length(x)==1&&grepl(',',x,fixed=TRUE))x<-strsplit(x,',',fixed=TRUE)[[1]];x<-trimws(as.character(x));x[nzchar(x)]};nu<-function(x,d){z<-suppressWarnings(as.numeric(x)[1]);if(is.na(z))d else z}
cols<-function(x,n){p<-c('#4477AA','#EE6677','#228833','#CCBB44','#66CCEE','#AA3377','#BBBBBB');z<-setNames(rep(p,length.out=length(n)),n);if(is.null(x))return(z);if(is.list(x))x<-unlist(x);if(is.null(names(x)))z[seq_len(min(length(x),length(z)))]<-x[seq_len(min(length(x),length(z)))]else z[intersect(names(x),n)]<-x[intersect(names(x),n)];z}
pick<-function(p,n,a,d){z<-ga(p,c(n,a),d);if(is.null(z)||length(z)==0) d else as.character(z[1])}
par<-if(!is.null(o$params)&&file.exists(o$params))fromJSON(o$params,simplifyVector=FALSE)else list();unlink(file.path(out,'error.json'));unlink(file.path(out,c('result.svg','result.pdf','result.png','result.html','figure.json','nodes_used.csv','edges_used.csv','selected_nodes.csv','positions.csv')));writeLines('',file.path(out,'run.log'))
d<-rt(o$input);mode<-tolower(as.character(gp(par,'input_mode','edge_list'))[1]);if(mode%in%c('network_venn','network-venn'))mode<-'membership';sc<-pick(par,'source_column',c('source','from'),'source');tc<-pick(par,'target_column',c('target','to'),'target')
if(mode=='membership'){gc<-pick(par,'group_column',c('group','set'),'group');ec<-pick(par,'node_id_column',c('element_column','element','member'),'element');if(!all(c(gc,ec)%in%names(d)))bad('Membership columns not found');g<-unique(as.character(d[[gc]]));m<-unique(as.character(d[[ec]]));n<-data.frame(id=c(g,m),label=c(g,m),group=c(g,rep('Member',length(m))),type=c(rep('Group',length(g)),rep('Member',length(m))),stringsAsFactors=FALSE);e<-data.frame(from=as.character(d[[gc]]),to=as.character(d[[ec]]),weight=1,edge_group=as.character(d[[gc]]),stringsAsFactors=FALSE)}else{if(!all(c(sc,tc)%in%names(d)))bad('Edge columns not found');n<-data.frame(id=unique(c(as.character(d[[sc]]),as.character(d[[tc]]))),stringsAsFactors=FALSE);n$label<-n$id;n$group<-'Network';n$type<-'Node';wc<-pick(par,'weight_column',c('weight'),NULL);eg<-pick(par,'edge_group_column',c('edge_group'),NULL);e<-data.frame(from=as.character(d[[sc]]),to=as.character(d[[tc]]),weight=if(is.null(wc))1 else suppressWarnings(as.numeric(d[[wc]])),edge_group=if(is.null(eg))'Edges' else as.character(d[[eg]]),stringsAsFactors=FALSE);e$weight[is.na(e$weight)]<-1}
if(!is.null(o$nodes)){z<-rt(o$nodes);idc<-pick(par,'node_id_column',c('node_id','id'),names(z)[1]);ix<-match(n$id,as.character(z[[idc]]));for(k in intersect(names(z),c('label','group','type','size','color','x','y','highlight','tooltip')))n[[k]]<-z[[k]][ix]}
n$degree<-tabulate(match(c(e$from,e$to),n$id),nbins=nrow(n));n$size<-if(mode=='membership')ifelse(n$type=='Group',nu(gp(par,'node_size_max',38),38),nu(gp(par,'node_size_min',13),13))else nu(gp(par,'node_size',18),18)+2*n$degree;n$label[is.na(n$label)|n$label=='']<-n$id;n$group[is.na(n$group)|n$group=='']<-'Network';n$highlight<-n$id%in%vv(ga(par,c('highlight_nodes','selected_nodes'),NULL));inc<-vv(gp(par,'nodes_include',NULL));exc<-vv(gp(par,'nodes_exclude',NULL));if(length(inc))n<-n[n$id%in%inc,,drop=FALSE];if(length(exc))n<-n[!n$id%in%exc,,drop=FALSE];e<-e[e$from%in%n$id&e$to%in%n$id,,drop=FALSE];n$group<-as.character(n$group);grps<-unique(n$group);cm<-cols(ga(par,c('group_colors','node_colors'),NULL),grps);n$color<-unname(cm[n$group]);n$color[is.na(n$color)]<-'#4477AA';n$title<-paste0('<b>',n$label,'</b><br>Group: ',n$group,'<br>Degree: ',n$degree);write.csv(n,file.path(out,'nodes_used.csv'),row.names=FALSE);write.csv(e,file.path(out,'edges_used.csv'),row.names=FALSE);if(any(n$highlight))write.csv(n[n$highlight,,drop=FALSE],file.path(out,'selected_nodes.csv'),row.names=FALSE)
set.seed(nu(gp(par,'seed',42),42));g<-graph_from_data_frame(e,directed=bn(gp(par,'directed',FALSE)),vertices=n);a<-tolower(as.character(gp(par,'layout_algorithm','fr'))[1]);xy<-if(a=='circle')layout_in_circle(g)else if(a=='kk')layout_with_kk(g)else if(a=='hierarchical')layout_as_tree(g)else if(all(c('x','y')%in%names(n)))cbind(as.numeric(n$x),as.numeric(n$y))else layout_with_fr(g);xy[is.na(xy)]<-0;n$x<-xy[,1];n$y<-xy[,2];if(bn(gp(par,'save_positions',FALSE)))write.csv(n[,c('id','x','y')],file.path(out,'positions.csv'),row.names=FALSE)
direct<-bn(gp(par,'directed',FALSE));types<-unique(as.character(n$type));shp<-setNames(rep(c(21,24,22,23,25),length.out=length(types)),types)
# Static figure: fillable shapes (so group colours show), white background, labels; node sizes are visNetwork px -> ggplot units.
p<-ggraph(g,layout='manual',x=n$x,y=n$y)+geom_edge_link(aes(width=weight),alpha=nu(gp(par,'edge_alpha',.65),.65),colour=gp(par,'edge_color','#718096'),arrow=if(direct)grid::arrow(length=grid::unit(3,'mm'))else NULL)+scale_edge_width(range=c(nu(gp(par,'edge_width_min',.4),.4),nu(gp(par,'edge_width_max',3),3)))+geom_node_point(aes(size=size/3,fill=group,shape=type),colour=gp(par,'node_stroke_color','#FFFFFF'),stroke=nu(gp(par,'node_stroke',.8),.8),alpha=nu(gp(par,'node_alpha',1),1))+scale_fill_manual(values=cm)+scale_shape_manual(values=shp)+scale_size_identity()+guides(fill=guide_legend(override.aes=list(shape=21,size=4)),shape=if(length(types)>1)guide_legend(override.aes=list(size=4,fill='grey60'))else'none')+theme_void()+theme(plot.background=element_rect(fill=gp(par,'plot_background','white'),colour=NA),plot.margin=margin(10,10,10,10))+ggtitle(gp(par,'title','Interactive network'))
if(bn(gp(par,'label_show',TRUE),TRUE))p<-p+geom_node_text(aes(label=label),repel=min(nu(gp(par,'width',9),9),nu(gp(par,'height',7),7))>=3,size=nu(gp(par,'label_size',3.2),3.2),colour=gp(par,'label_color','#222222'));if (!exists('omicscanvas_apply_theme')) { .oc_f <- sub('^--file=', '', grep('^--file=', commandArgs(FALSE), value = TRUE)[1]); .oc_rt <- file.path(dirname(normalizePath(.oc_f, mustWork = FALSE)), '..', '..', 'R', 'runtime', 'omicscanvas_theme.R'); if (!file.exists(.oc_rt)) .oc_rt <- file.path('R', 'runtime', 'omicscanvas_theme.R'); sys.source(.oc_rt, envir = globalenv()) }; p <- omicscanvas_apply_theme(p, par, only = c('base_size', 'font_family', 'grid_color', 'grid_show', 'legend_key_size', 'legend_position', 'legend_show', 'legend_text_size', 'legend_title_size', 'margin', 'panel_background', 'panel_border_color', 'panel_border_show', 'panel_border_width', 'title_color', 'title_face', 'title_hjust', 'title_size')); w<-nu(gp(par,'width',9),9);h<-nu(gp(par,'height',7),7);ggsave(file.path(out,'result.svg'),p,width=w,height=h);ggsave(file.path(out,'result.pdf'),p,width=w,height=h);ggsave(file.path(out,'result.png'),p,width=w,height=h,dpi=nu(gp(par,'dpi',300),300))
v<-visNetwork(n,e,main=gp(par,'title','Interactive network'),height=paste0(nu(gp(par,'html_height',700),700),'px'))%>%visNodes(label='label',title='title',value='size',color=list(background='color',border=gp(par,'node_stroke_color','#FFFFFF')),shape='dot')%>%visEdges(width='weight',title='edge_group',arrows=if(direct)'to' else '')%>%visOptions(highlightNearest=bn(gp(par,'highlight_neighborhood',TRUE),TRUE))%>%visInteraction(dragNodes=bn(gp(par,'drag_nodes',TRUE),TRUE),zoomView=bn(gp(par,'zoom_view',TRUE),TRUE),navigationButtons=bn(gp(par,'navigation_buttons',TRUE),TRUE),hover=bn(gp(par,'tooltip_show',TRUE),TRUE),selectable=bn(gp(par,'selectable',TRUE),TRUE))%>%visPhysics(enabled=bn(gp(par,'physics_enabled',FALSE),FALSE),stabilization=list(enabled=bn(gp(par,'stabilize',TRUE),TRUE)));saveWidget(v,file.path(out,'result.html'),selfcontained=TRUE);fig<-list(plugin='interactive_network_plot',input_mode=mode,node_count=nrow(n),edge_count=nrow(e),positions_saved=bn(gp(par,'save_positions',FALSE)),outputs=list(svg='result.svg',pdf='result.pdf',png='result.png',html='result.html',nodes='nodes_used.csv',edges='edges_used.csv',log='run.log'));writeLines(toJSON(fig,auto_unbox=TRUE,pretty=TRUE),file.path(out,'figure.json'));log('Completed interactive network plot.')
tryCatch({main<-TRUE},error=function(x)bad('Interactive network plot failed',conditionMessage(x)))
